/* tests/abi_test.c: the C ABI against the Lean reference (run by scripts/test_abi.sh; test code, not shipped).
 * Usage: abi_test VECTORS.jsonl     (rows of vbm-json-vectors-1, generated by the Lean REFERENCE: verdict, error code, canonical form).
 * A DRIVER: it holds no input document of its own. Every document it parses is a row of the generated set (the 100000-deep arrays and objects are rows: set `depth`), and the crafted export
 * results of the fault injection are ENUMERATED over the boundary values of the result layout and judged by a model of the layout contract (include/vbm_json.h), not listed by hand.
 * It checks (1) every row's verdict and error code through vbm_json_parse, and for an accepted row reads the TAPE back with an independent reader (strict: bounds, subtree sizes,
 * text order) and compares the compact form with the reference's canonical bytes; (2) a failing allocator is VBM_JSON_NOMEM and every allocation is released, on a row's input;
 * (3) no growth of resident memory over many parses of rows, ok and failing (VBM_JSON_TEST_LEAK=1 leaks on purpose: this check must then FAIL). Exit 0 = all pass. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <lean/lean.h>
#include "../include/vbm_json.h"

typedef struct { char *p; size_t n, cap; } buf;
static void put(buf *b, const void *s, size_t n) {
  if (b->n + n > b->cap) { b->cap = (b->n + n) * 2 + 64; b->p = realloc(b->p, b->cap); if (!b->p) abort(); }
  memcpy(b->p + b->n, s, n); b->n += n;
}
static void putc_(buf *b, char c) { put(b, &c, 1); }

/* the tape reader: prints the compact JSON of the node at *i, advancing *i; *cur is the text cursor (texts are in document order). Returns 0, or -1 on a malformed tape. */
static int node(const vbm_json_tape *t, size_t *i, size_t *cur, buf *o, int depth) {
  if (depth > 600 || *i + 2 > t->nwords) return -1;
  size_t at = *i; uint64_t head = t->words[at], aux = t->words[at + 1]; unsigned kind = head & 0xff; uint64_t len = head >> 8;
  *i += 2;
  switch (kind) {
  case VBM_JSON_NULL: case VBM_JSON_FALSE: case VBM_JSON_TRUE:
    if (len || aux) return -1;
    put(o, kind == VBM_JSON_NULL ? "null" : kind == VBM_JSON_FALSE ? "false" : "true", kind == VBM_JSON_FALSE ? 5 : 4); return 0;
  case VBM_JSON_NUMBER: case VBM_JSON_STRING: {
    if (aux != *cur || len > t->ntext || aux > t->ntext - len) return -1;
    const uint8_t *s = t->text + aux; *cur += len;
    if (kind == VBM_JSON_NUMBER) { put(o, s, len); return 0; }
    putc_(o, '"');
    for (uint64_t k = 0; k < len; k++) {
      uint8_t c = s[k];
      if (c == '"') put(o, "\\\"", 2); else if (c == '\\') put(o, "\\\\", 2);
      else if (c == 8) put(o, "\\b", 2); else if (c == 12) put(o, "\\f", 2); else if (c == 10) put(o, "\\n", 2);
      else if (c == 13) put(o, "\\r", 2); else if (c == 9) put(o, "\\t", 2);
      else if (c < 0x20) { char e[8]; snprintf(e, sizeof e, "\\u00%02x", c); put(o, e, 6); }
      else putc_(o, (char)c);
    }
    putc_(o, '"'); return 0; }
  case VBM_JSON_ARRAY: case VBM_JSON_OBJECT: {
    if (aux < 2 || aux > t->nwords - at) return -1;
    putc_(o, kind == VBM_JSON_ARRAY ? '[' : '{');
    for (uint64_t k = 0; k < len; k++) {
      if (k) putc_(o, ',');
      if (kind == VBM_JSON_OBJECT) {
        if (*i + 2 > t->nwords || (t->words[*i] & 0xff) != VBM_JSON_STRING) return -1;
        if (node(t, i, cur, o, depth + 1)) return -1;
        putc_(o, ':');
      }
      if (node(t, i, cur, o, depth + 1)) return -1;
    }
    putc_(o, kind == VBM_JSON_ARRAY ? ']' : '}');
    return *i == at + aux ? 0 : -1; }
  default: return -1;
  }
}

static int read_tape(const vbm_json_tape *t, buf *o) {
  size_t i = 0, cur = 0;
  if (node(t, &i, &cur, o, 0)) return -1;
  return i == t->nwords && cur == t->ntext ? 0 : -1;
}

static int hexval(int c) { return c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : -1; }
/* the string value of "key":" in a row, as bytes (hex-decoded when hex), or NULL */
static const char *field(const char *line, const char *key, size_t *n) {
  char k[40]; snprintf(k, sizeof k, "\"%s\":\"", key);
  const char *p = strstr(line, k); if (!p) return NULL;
  p += strlen(k); const char *q = strchr(p, '"'); if (!q) return NULL;
  *n = (size_t)(q - p); return p;
}
static uint8_t *unhex(const char *h, size_t n, size_t *out) {
  if (n % 2) return NULL;
  uint8_t *r = malloc(n / 2 + 1); if (!r) abort();
  for (size_t k = 0; k < n / 2; k++) { int a = hexval(h[2 * k]), b = hexval(h[2 * k + 1]); if (a < 0 || b < 0) { free(r); return NULL; } r[k] = (uint8_t)(a * 16 + b); }
  *out = n / 2; return r;
}

static int failures;
/* sample inputs taken from the generated rows (no document of the test's own): the first small accepted row with an object and text, and the first small syntax-error row */
static uint8_t *samp; static size_t samp_n; static uint8_t *esamp; static size_t esamp_n;
static void fail(const char *fmt, const char *what, size_t id) { fprintf(stderr, "FAIL row %zu (%s): ", id, what); fprintf(stderr, "%s\n", fmt); failures++; }

static int run_rows(const char *path) {
  FILE *f = fopen(path, "r"); if (!f) { perror(path); return 1; }
  char *line = NULL; size_t cap = 0; ssize_t got; size_t rows = 0, ok = 0, err_syntax = 0, err_depth = 0;
  while ((got = getline(&line, &cap, f)) > 0) {
    size_t id = ++rows, n;
    const char *h = field(line, "input", &n); size_t ilen;
    uint8_t *in = h ? unhex(h, n, &ilen) : NULL;
    const char *v = field(line, "verdict", &n);
    if (!in || !v) { fail("malformed row", "?", id); continue; }
    vbm_json_tape t; int rc = vbm_json_parse(in, ilen, NULL, &t);
    if (!strncmp(v, "ok", n)) {
      size_t cn; const char *c = field(line, "canonical", &cn); size_t clen; uint8_t *canon = c ? unhex(c, cn, &clen) : NULL;
      if (!canon) fail("no canonical form", "ok", id);
      else if (rc != VBM_JSON_OK) fail("the reference accepts, the ABI rejects", "ok", id);
      else {
        buf o = {0};
        if (read_tape(&t, &o)) fail("the tape is malformed", "ok", id);
        else if (o.n != clen || memcmp(o.p, canon, clen)) fail("the tape does not read back to the canonical form", "ok", id);
        else { ok++; if (!samp && ilen >= 24 && ilen <= 300 && t.ntext >= 4 && memchr(in, '{', ilen)) { samp = malloc(ilen); memcpy(samp, in, ilen); samp_n = ilen; } }
        free(o.p);
      }
      free(canon);
    } else {
      size_t cn; const char *c = field(line, "code", &cn);
      int want = c && !strncmp(c, "syntax", cn) ? VBM_JSON_SYNTAX : c && !strncmp(c, "depth", cn) ? VBM_JSON_DEPTH : -1;
      if (rc != want) fail("the verdict or the error code differs from the reference", c ? "err" : "err?", id);
      else if (rc == VBM_JSON_SYNTAX) { err_syntax++; if (!esamp && ilen >= 3 && ilen <= 300) { esamp = malloc(ilen); memcpy(esamp, in, ilen); esamp_n = ilen; } } else err_depth++;
      if (rc != VBM_JSON_OK && (t.words || t.text)) fail("a rejected parse left a tape", "err", id);
    }
    vbm_json_free(&t); free(in);
  }
  free(line); fclose(f);
  printf("abi_test: %zu rows (%zu accepted and read back to the canonical form, %zu syntax errors, %zu depth errors)\n", rows, ok, err_syntax, err_depth);
  if (rows < 1000) { fprintf(stderr, "FAIL: only %zu rows\n", rows); failures++; }
  if (!samp || !esamp) { fprintf(stderr, "FAIL: the rows have no small accepted object and no small syntax error to build the allocator and leak checks on\n"); failures++; }
  return 0;
}

typedef struct { long live, calls; long fail_at; size_t last; } counting;
static void *c_alloc(void *ctx, size_t n) { counting *c = ctx; c->calls++; if (c->fail_at && c->calls >= c->fail_at) return NULL; c->live++; c->last = n; return malloc(n); }
static void c_free(void *ctx, void *p, size_t n) { counting *c = ctx; c->live--; if (n != c->last) c->live += 1000000; free(p); }

/* The default allocator's block (no allocator given): inside a Lean ByteArray payload, 8-aligned, the byte before it is its distance back to the payload's start (1..8), the payload holds the block and 8 more bytes. */
static void default_block(void) {
  vbm_json_tape t;
  if (vbm_json_parse(samp, samp_n, NULL, &t) != VBM_JSON_OK) { fail("the default allocator did not parse", "default", 0); return; }
  const unsigned char *blk = t.block_; unsigned delta = blk[-1]; int found = 0;
  if ((uintptr_t)blk % 8) fail("the default block is not 8-aligned", "default", 0);
  if (delta < 1 || delta > 8) fail("the default block's distance byte is outside 1..8", "default", delta);
  else {
    lean_sarray_object *o = (lean_sarray_object *)(blk - delta - offsetof(lean_sarray_object, m_data));
    found = o->m_header.m_tag == LeanScalarArray && o->m_size == t.block_size_ + 8 && o->m_capacity == t.block_size_ + 8 && lean_sarray_cptr((lean_object *)o) == blk - delta;
  }
  if (!found) fail("the default block is not the payload of a ByteArray of its size plus 8", "default", 0);
  if (found) {   /* freeing must release exactly that ByteArray: hold a second reference, free, and see the count back at one */
    lean_object *o = (lean_object *)(blk - delta - offsetof(lean_sarray_object, m_data));
    vbm_json_tape t2 = t;   /* the second reference is released by the library itself (its runtime may not be the one this test links) */
    lean_inc_ref(o); vbm_json_free(&t);
    if (!lean_is_exclusive(o)) fail("vbm_json_free did not release the block's ByteArray", "default", 0);
    vbm_json_free(&t2);
  } else vbm_json_free(&t);
}

static void allocator(void) {
  default_block();
  counting c = {0}; vbm_json_allocator al = { &c, c_alloc, c_free }; vbm_json_opts o = { sizeof o, &al };
  vbm_json_tape t; int rc = vbm_json_parse(samp, samp_n, &o, &t);
  if (rc != VBM_JSON_OK || c.live != 1 || c.calls != 1) fail("the embedder's allocator is not used exactly once", "alloc", 0);
  if (c.last != 8 * t.nwords + t.ntext) fail("the block is not exactly the words and the text", "alloc", 0);
  vbm_json_free(&t); vbm_json_free(&t);
  if (c.live != 0) fail("the tape's memory is not released with the same size", "alloc", 0);
  c.fail_at = 1; c.calls = 0;
  rc = vbm_json_parse(samp, samp_n, &o, &t);
  if (rc != VBM_JSON_NOMEM || t.words || c.live != 0) fail("a failing allocator is not VBM_JSON_NOMEM with nothing held", "alloc", 0);
  vbm_json_opts bad = { sizeof o, &(vbm_json_allocator){ 0, 0, 0 } };
  if (vbm_json_parse(samp, samp_n, &bad, &t) != VBM_JSON_ARG) fail("an allocator with no functions is not VBM_JSON_ARG", "alloc", 0);
  for (size_t sz = 0; sz < sizeof o; sz += 4) {   /* an opts struct too old to carry the allocator is refused; its full size is accepted */
    vbm_json_opts old = { sz, &al };
    if (vbm_json_parse(samp, samp_n, &old, &t) != VBM_JSON_ARG) fail("opts too short to hold the allocator are not VBM_JSON_ARG", "alloc", sz);
  }
  vbm_json_allocator half[2] = { { &c, c_alloc, 0 }, { &c, 0, c_free } };   /* both functions are required, each on its own */
  for (int k = 0; k < 2; k++) { vbm_json_opts ho = { sizeof o, &half[k] }; if (vbm_json_parse(samp, samp_n, &ho, &t) != VBM_JSON_ARG) fail("an allocator missing one function is not VBM_JSON_ARG", "alloc", (size_t)k); }
  if (vbm_json_parse(NULL, 5, NULL, &t) != VBM_JSON_ARG || vbm_json_parse(samp, 3, NULL, NULL) != VBM_JSON_ARG) fail("bad arguments are not VBM_JSON_ARG", "alloc", 0);
  if (vbm_json_parse(NULL, 0, NULL, &t) != VBM_JSON_SYNTAX) fail("the empty input is not VBM_JSON_SYNTAX", "alloc", 0);
  printf("abi_test: the allocator hook is used once, released with its size; a failing one is VBM_JSON_NOMEM; bad arguments are VBM_JSON_ARG\n");
}

/* Fault injection: the shim's own checks of what the Lean export hands back (the result header status, words, text, and the sizes), which a correct export never trips. The shim source is compiled a SECOND
 * time into this file (so a mutant of abi/vbm_json.c is also a mutant of this copy) under other names, against a fake export that returns the bytes the case asks for; likewise the allocation and copy of
 * an input of LEAN_MAX_SMALL_NAT bytes are stubbed (the real runtime would abort on out-of-memory, T09), so the bound of the length check is tested at its edge. */
static const uint8_t *fx_bytes; static size_t fx_n;
lean_object *fx_export(lean_object *in) { lean_dec_ref(in); lean_object *o = lean_alloc_sarray(1, fx_n, fx_n); if (fx_n) memcpy(lean_sarray_cptr(o), fx_bytes, fx_n); return o; }
lean_object *fx_init(uint8_t builtin) { (void)builtin; return lean_io_result_mk_ok(lean_box(0)); }
static lean_object *fx_alloc_sarray(unsigned elem, size_t size, size_t cap) { return lean_alloc_sarray(elem, size > 4096 ? 0 : size, size > 4096 ? 0 : cap); }
static void *fx_memcpy(void *d, const void *s, size_t n) { return n > 4096 ? d : memcpy(d, s, n); }
#define vbm_json_parse fx_parse
#define vbm_json_free fx_free
#define vbm_json_parse_tape fx_export
#define initialize_vbm_x2djson_LeanJson_Tape fx_init
#define lean_alloc_sarray fx_alloc_sarray
#define memcpy fx_memcpy
#include "../abi/vbm_json.c"
#undef memcpy
#undef lean_alloc_sarray
#undef initialize_vbm_x2djson_LeanJson_Tape
#undef vbm_json_parse_tape
#undef vbm_json_free
#undef vbm_json_parse

/* a result of n bytes whose header says (status, nw, nt) and whose payload is a known pattern; returns the shim's code and, when it accepted, checks the block it built */
static int fx_case(uint64_t status, uint64_t nw, uint64_t nt, size_t n, vbm_json_opts *opts) {
  uint8_t r[256]; memset(r, 0, sizeof r); for (size_t k = 24; k < n; k++) r[k] = (uint8_t)(k * 7 + 1);
  memcpy(r, &status, 8); memcpy(r + 8, &nw, 8); memcpy(r + 16, &nt, 8);
  fx_bytes = r; fx_n = n; vbm_json_tape t; uint8_t in = 0;
  int rc = fx_parse(&in, 1, opts, &t);
  if (rc == VBM_JSON_OK) {
    if (!t.words || t.nwords != nw || t.ntext != nt || memcmp(t.words, r + 24, 8 * nw) || memcmp(t.text, r + 24 + 8 * nw, nt) || t.text != (const uint8_t *)t.words + 8 * nw) fail("an accepted header built a wrong tape", "fault", n);
    fx_free(&t);
  } else if (t.words || t.text || t.nwords || t.ntext) fail("a refused header left a tape", "fault", n);
  return rc;
}

/* The contract of the export result (include/vbm_json.h, abi/Abi.lean): 24 header bytes (status, words, text bytes) then exactly 8*words + text bytes. Status 1 and 2 are the syntax and depth errors and
 * carry nothing (the result is exactly the header); status 0 is a tape and the sizes must add up EXACTLY, without wrapping; any other status, or fewer than 24 bytes, is VBM_JSON_INTERNAL. */
static int model(uint64_t status, uint64_t nw, uint64_t nt, size_t n) {
  if (n < 24) return VBM_JSON_INTERNAL;
  if (status == 1 || status == 2) return n == 24 && nw == 0 && nt == 0 ? (status == 1 ? VBM_JSON_SYNTAX : VBM_JSON_DEPTH) : VBM_JSON_INTERNAL;
  if (status != 0) return VBM_JSON_INTERNAL;
  unsigned __int128 need = (unsigned __int128)24 + (unsigned __int128)nw * 8 + nt;
  return need == n ? VBM_JSON_OK : VBM_JSON_INTERNAL;
}

static void fault(void) {
  /* enumerated, not listed: every status, and the boundary values of both sizes (small, and around 2^64/8 and 2^64 where a wrapping sum would agree), against the result lengths that are
   * the exact sum, one off it either way, and the header-only lengths; the model above judges each */
  const uint64_t sts[] = { 0, 1, 2, 3, UINT64_MAX }, nws[] = { 0, 1, 2, 3, 5, UINT64_MAX / 8 + 1, UINT64_MAX / 8 + 2, UINT64_MAX / 8, UINT64_MAX },
                 nts[] = { 0, 1, 2, 3, 5, 7, 9, 16, UINT64_MAX - 15, UINT64_MAX - 7, UINT64_MAX };
  size_t cases = 0, ok = 0;
  for (size_t a = 0; a < sizeof sts / 8; a++) for (size_t b = 0; b < sizeof nws / 8; b++) for (size_t c = 0; c < sizeof nts / 8; c++) {
    size_t ns[16], k = 0;
    ns[k++] = 0; ns[k++] = 23; ns[k++] = 24; ns[k++] = 25; ns[k++] = 32; ns[k++] = 40;
    if (nws[b] < 8 && nts[c] < 20) { size_t e = 24 + 8 * nws[b] + nts[c]; ns[k++] = e - 1; ns[k++] = e; ns[k++] = e + 1; }
    for (size_t j = 0; j < k; j++) {
      if (ns[j] > 255) continue;
      int want = model(sts[a], nws[b], nts[c], ns[j]), got = fx_case(sts[a], nws[b], nts[c], ns[j], NULL);
      cases++; ok += want == VBM_JSON_OK;
      if (got != want) fail("the shim's verdict on a crafted export result differs from the layout contract", "fault", cases);
    }
  }
  if (ok < 20) fail("the enumeration reached too few accepted headers", "fault", ok);
  /* the block asked of the embedder is the words and the text and not a byte more (an empty tape asks for 8) */
  counting c = {0}; vbm_json_allocator al = { &c, c_alloc, c_free }; vbm_json_opts o = { sizeof o, &al };
  for (uint64_t nw = 0; nw < 4; nw++) for (uint64_t nt = 0; nt < 10; nt++) {
    if (fx_case(0, nw, nt, 24 + 8 * nw + nt, &o) != VBM_JSON_OK || c.last != (nw || nt ? 8 * nw + nt : 8) || c.live != 0) fail("the block asked for is not 8 * words + text (8 for an empty tape)", "fault", nw * 10 + nt);
  }
  /* the edge of the length check: LEAN_MAX_SMALL_NAT bytes pass it (the runtime decides whether they fit), one more is an argument error */
  static const uint8_t syn[24] = { 1 }; fx_bytes = syn; fx_n = 24; vbm_json_tape t; uint8_t in = 0;
  if (fx_parse(&in, (size_t)LEAN_MAX_SMALL_NAT, NULL, &t) != VBM_JSON_SYNTAX) fail("an input of LEAN_MAX_SMALL_NAT bytes is refused", "fault", 2);
  if (fx_parse(&in, (size_t)LEAN_MAX_SMALL_NAT + 1, NULL, &t) != VBM_JSON_ARG) fail("an input over LEAN_MAX_SMALL_NAT bytes is not VBM_JSON_ARG", "fault", 3);
  printf("abi_test: the shim agrees with the layout contract on %zu enumerated export results (%zu accepted), asks for exactly words + text, and its length check is exact at its edge\n", cases, ok);
}

static long rss_pages(void) { long a = 0, r = 0; FILE *f = fopen("/proc/self/statm", "r"); if (!f) return -1; if (fscanf(f, "%ld %ld", &a, &r) != 2) r = -1; fclose(f); return r; }

static void leak(void) {
  counting c = {0}; vbm_json_allocator al = { &c, c_alloc, c_free }; vbm_json_opts o = { sizeof o, &al };
  int deliberate = getenv("VBM_JSON_TEST_LEAK") != NULL, iters = 30000; long base = 0;
  for (int i = 0; i < iters + 1000; i++) {
    if (i == 1000) base = rss_pages();
    vbm_json_tape t; c.fail_at = (i % 2) ? 1 : 0; c.calls = 0;
    int rc = vbm_json_parse(samp, samp_n, &o, &t);
    if (rc == VBM_JSON_OK) vbm_json_free(&t);
    if (i % 7 == 0) { vbm_json_tape e; if (vbm_json_parse(esamp, esamp_n, &o, &e) == VBM_JSON_OK) vbm_json_free(&e); }
    if (deliberate) memset(malloc(1024), 1, 1024);
  }
  long growth = (rss_pages() - base) * (sysconf(_SC_PAGESIZE) / 1024);
  if (c.live != 0 || growth > 4096) { fprintf(stderr, "FAIL: leak: %ld KiB resident growth over %d parses, %ld allocations live\n", growth, iters, c.live); failures++; }
  else printf("abi_test: no leak: %ld KiB resident growth over %d parses (ok and failing allocator alternating)\n", growth, iters);
}

/* a crash is a failure of the test, reported and exited: no core dump (a broken shim or a mutant of it may crash) */
static void on_crash(int sig) { static const char m[] = "abi_test: FAIL: the test crashed\n"; if (write(2, m, sizeof m - 1) < 0) {} _exit(128 + sig); }

int main(int argc, char **argv) {
  signal(SIGSEGV, on_crash); signal(SIGBUS, on_crash); signal(SIGABRT, on_crash);
  if (argc != 2) { fprintf(stderr, "usage: abi_test VECTORS.jsonl\n"); return 2; }
  if (run_rows(argv[1])) return 1;
  allocator(); fault(); leak();
  if (failures) { fprintf(stderr, "abi_test: %d failure(s)\n", failures); return 1; }
  printf("abi_test: ok\n"); return 0;
}
